import re
import numpy as np
import pandas as pd
import torch
from PIL import Image
from scipy import ndimage
from scipy.ndimage import label, center_of_mass
from scipy.spatial.distance import pdist
from scipy.signal import find_peaks
WINDOW = 3

MIN_GAP = 2

INK_K = 2.0

def crop_rgb(img, box, scale=1.0, strip=2000):
    x0, y0, x1, y1 = box
    out = Image.new('RGB', (round((x1 - x0) * scale), round((y1 - y0) * scale)))
    for ys in range(y0, y1, strip):
        ye = min(ys + strip, y1)
        part = img.crop((x0, ys, x1, ye)).convert('RGB')
        top, bottom = (round((ys - y0) * scale), round((ye - y0) * scale))
        if scale != 1.0:
            part = part.resize((out.width, max(1, bottom - top)), Image.Resampling.BOX)
        out.paste(part, (0, top))
    return out

H = 8

def trim_borders(col):
    dark = col.mean(2, dtype=np.float32) < 100
    profile = dark.mean(0)
    idx = np.where(profile > 0.6)[0]
    mid = col.shape[1] // 2
    left, right = (idx[idx < mid], idx[idx >= mid])
    x0 = left.max() + 3 if left.size else 0
    x1 = right.min() - 2 if right.size else col.shape[1]
    return col if x1 - x0 < 10 else col[:, x0:x1]

def stripe_features(stripe, thresh=128, max_comp=2000):
    black = stripe.mean(2, dtype=np.float32) < thresh
    density = black.mean()
    bg = stripe[~black]
    bg_rgb = bg.mean(0) / 255.0 if len(bg) else np.ones(3)
    lab, n = label(black, structure=np.ones((3, 3)))
    if n == 0:
        return np.array([density, 0, 0, 0, *bg_rgb], np.float32)
    ids = np.arange(1, n + 1)
    sizes = np.bincount(lab.ravel(), minlength=n + 1)[1:]
    if n > 1:
        cen = np.array(center_of_mass(black, lab, ids))
        if n > max_comp:
            cen = cen[np.random.default_rng(0).choice(n, max_comp, replace=False)]
        mean_dist = pdist(cen).mean()
    else:
        mean_dist = 0.0
    return np.array([density, n, mean_dist, sizes.mean(), *bg_rgb], np.float32)

def column_to_vectors(col, h=H):
    col = trim_borders(col)
    return [stripe_features(col[s:s + h]) for s in range(0, len(col), h)]

def raw_stripe_features(col, h=H):
    return np.stack(column_to_vectors(col, h)).astype(np.float32)

def zscore(R):
    scale = R.std(0)
    scale[scale < 1e-06] = 1.0
    return (R - R.mean(0)) / scale

def column_features(col, h=H):
    return zscore(raw_stripe_features(col, h))

def to_table(peaks, n_rows, y_offset, h=H):
    edges = np.concatenate([[0], np.sort(peaks) * h, [n_rows]]).astype(int)
    return pd.DataFrame({'y_top': edges[:-1] + y_offset, 'y_bottom': edges[1:] + y_offset})

def boundary_score(F, w=WINDOW):
    c = np.vstack([np.zeros((1, F.shape[1])), np.cumsum(F, 0)])
    n = len(F)
    ys = np.arange(w, n - w)
    above = (c[ys] - c[ys - w]) / w
    below = (c[ys + w] - c[ys]) / w
    score = np.zeros(n)
    score[ys] = np.linalg.norm(below - above, axis=1)
    return score

def robust_threshold(s, k):
    med = np.median(s)
    mad = 1.4826 * np.median(np.abs(s - med))
    return max(med + k * max(mad, 1e-06), 1.0)

def ink_boundaries(F, w=WINDOW, k=INK_K, gap=MIN_GAP):
    s = boundary_score(F, w)
    peaks, _ = find_peaks(s, height=robust_threshold(s, k), distance=gap)
    return peaks

NON_ROCK = re.compile('\\b(core|dst|shoe|survey|mud (loss|gain)|lot|fit|rft|mdt|sidewall|casing|fossils?|foraminifera|diatoms?|gas|oil|show|cuttings|sample|bit|trip)\\b', re.I)

def is_rock(label):
    return not NON_ROCK.search(label or '')

def box_iou(a, b):
    ix = max(0, min(a[2], b[2]) - max(a[0], b[0]))
    iy = max(0, min(a[3], b[3]) - max(a[1], b[1]))
    union = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - ix * iy
    return ix * iy / union if union else 0.0

def detect_swatches(img, legend_box, min_w=25, max_w=200, min_h=15, max_h=120, max_aspect=8):
    lx0, ly0, _, _ = legend_box
    rgb = np.array(crop_rgb(img, legend_box)).astype(np.int16)

    def candidates(mask):
        lines = ndimage.binary_opening(mask, np.ones((1, max_w + 1))) | ndimage.binary_opening(mask, np.ones((max_h + 1, 1)))
        lab, _ = ndimage.label(mask & ~lines)
        for i, sl in enumerate(ndimage.find_objects(lab), 1):
            y0, y1, x0, x1 = (sl[0].start, sl[0].stop, sl[1].start, sl[1].stop)
            w, h = (x1 - x0, y1 - y0)
            if min_w <= w <= max_w and min_h <= h <= max_h and (0.7 <= w / h <= max_aspect):
                yield (lab[y0:y1, x0:x1] == i, (x0 + lx0, y0 + ly0, x1 + lx0, y1 + ly0))
    framed = []
    for m, b in candidates(rgb.mean(2) < 110):
        sides = [max((m[k].mean() for k in (0, 1, 2))), max((m[-k].mean() for k in (1, 2, 3))), max((m[:, k].mean() for k in (0, 1, 2))), max((m[:, -k].mean() for k in (1, 2, 3)))]
        if min(sides) >= 0.8:
            framed.append(b)
    solid = [b for m, b in candidates((255 - rgb).max(2) > 40) if ndimage.binary_fill_holes(m).mean() >= 0.9]
    boxes = framed + [b for b in solid if not any((box_iou(b, f) > 0.3 for f in framed))]
    boxes = [b for b in boxes if not any((o != b and o[0] <= b[0] and (o[1] <= b[1]) and (o[2] >= b[2]) and (o[3] >= b[3]) for o in boxes))]
    return sorted(boxes, key=lambda b: (round(b[1] / 20), b[0]))

def read_swatch_labels(img, boxes, legend_box, text_px=64, pad=4, trace=None):
    try:
        import easyocr
    except ImportError:
        print('easyocr not installed (pip install easyocr): swatches will be named legend_<id>')
        return [None] * len(boxes)
    if not hasattr(read_swatch_labels, 'reader'):
        read_swatch_labels.reader = easyocr.Reader(['en'], gpu=torch.cuda.is_available(), verbose=False, model_storage_directory=str(OUTPUT_DIR / 'ocr_models'), user_network_directory=str(OUTPUT_DIR / 'ocr_networks'))
    names = []
    for bi, (x0, y0, x1, y1) in enumerate(boxes):
        h = y1 - y0
        step = {'i': bi, 'swatch': (x0, y0, x1, y1), 'search': None, 'line': None, 'crop': None, 'text': None}
        if trace is not None:
            trace.append(step)
        right = [b[0] for b in boxes if b[0] > x1 and abs(b[1] - y0) < h / 2]
        xe = min(min(right) - 4 if right else legend_box[2], x1 + 5 * (x1 - x0))
        step['search'] = (x1 + 2, y0 - h, xe, y1 + h)
        if xe <= x1 + 2:
            names.append(None)
            continue
        band = np.array(img.crop((x1 + 2, y0 - h, xe, y1 + h)).convert('L'))
        ink = band < 160
        rules = np.zeros_like(ink)
        rules[:, ink.mean(0) > 0.9] = True
        rules[ink.mean(1) > 0.9, :] = True
        band = np.where(rules, 255, band)
        ink &= ~rules
        edges = np.flatnonzero(np.diff(np.r_[0, ink.any(1).astype(np.int8), 0]))
        runs = [r for r in zip(edges[::2], edges[1::2]) if min(r[1], 2 * h) > max(r[0], h)]
        if not runs:
            names.append(None)
            continue
        a, b = max(runs, key=lambda r: min(r[1], 2 * h) - max(r[0], h))
        cols = np.flatnonzero(ink[a:b].any(0))
        crop = band[max(a - pad, 0):b + pad, max(cols[0] - pad, 0):cols[-1] + pad].astype(np.uint8)
        step['line'] = (x1 + 2 + cols[0], y0 - h + a, x1 + 2 + cols[-1], y0 - h + b)
        step['crop'] = crop
        f = max(1.0, text_px / crop.shape[0])
        crop = Image.fromarray(crop).resize((round(crop.shape[1] * f), round(crop.shape[0] * f)), Image.LANCZOS)
        crop = np.pad(np.array(crop), 12, constant_values=255)
        names.append(' '.join(read_swatch_labels.reader.readtext(crop, detail=0, paragraph=True)).strip() or None)
        step['text'] = names[-1]
    return names

def swatch_pixels(img, box, inset=3):
    x0, y0, x1, y1 = box
    return np.array(img.crop((x0 + inset, y0 + inset, x1 - inset, y1 - inset)).convert('RGB'))

RUN_BINS = np.array([1, 2, 3, 4, 6, 9, 13, 21, 10 ** 6])

W_COLOR, W_INK, W_TEXTURE, TEXTURE_FULL_PX = (1 / 10, 4.0, 1.0, 24)

def srgb_to_lab(rgb):
    c = np.asarray(rgb, np.float64) / 255.0
    c = np.where(c > 0.04045, ((c + 0.055) / 1.055) ** 2.4, c / 12.92)
    xyz = c @ np.array([[0.4124, 0.3576, 0.1805], [0.2126, 0.7152, 0.0722], [0.0193, 0.1192, 0.9505]]).T
    xyz = xyz / np.array([0.95047, 1.0, 1.08883])
    f = np.where(xyz > 0.008856, np.cbrt(xyz), 7.787 * xyz + 16 / 116)
    return np.array([116 * f[1] - 16, 500 * (f[0] - f[1]), 200 * (f[1] - f[2])])

def run_hist(mask):
    m = np.pad(mask.astype(np.int8), ((0, 0), (1, 1)))
    d = np.diff(m, axis=1)
    lengths = np.where(d == -1)[1] - np.where(d == 1)[1]
    h = np.histogram(lengths, bins=RUN_BINS, weights=lengths)[0].astype(np.float64)
    return h / h.sum() if h.sum() else h

def describe(rgb):
    rgb = np.asarray(rgb)
    dark = rgb.mean(2) < 128
    light = rgb[~dark]
    return {'lab': srgb_to_lab(np.median(light, 0) if len(light) else np.zeros(3)), 'ink': float(dark.mean()), 'h_dark': run_hist(dark), 'v_dark': run_hist(dark.T), 'h_gap': run_hist(~dark), 'v_gap': run_hist(~dark.T), 'rows': rgb.shape[0]}

def descriptor_distance(seg, sw):
    tv = lambda k: 0.5 * np.abs(seg[k] - sw[k]).sum()
    v_weight = min(1.0, seg['rows'] / TEXTURE_FULL_PX)
    d_tex = (tv('h_dark') + tv('h_gap') + v_weight * (tv('v_dark') + tv('v_gap'))) / 4
    return np.linalg.norm(seg['lab'] - sw['lab']) * W_COLOR + abs(seg['ink'] - sw['ink']) * W_INK + W_TEXTURE * d_tex

NB = len(RUN_BINS) - 1

BLANK = {'lab': srgb_to_lab([255, 255, 255]), 'ink': 0.0, 'h_dark': np.zeros(NB), 'v_dark': np.zeros(NB), 'h_gap': np.eye(NB)[-1], 'v_gap': np.eye(NB)[-1], 'rows': 1}

def prototypes(legend, img, rocks_only=True):
    leg = legend.loc[legend.lithology.map(is_rock).astype(bool)] if rocks_only else legend
    return [(-1, 'blank', BLANK)] + [(r.legend_id, r.lithology, describe(swatch_pixels(img, r.box))) for r in leg.itertuples()]

SPLIT_WINDOW, SPLIT_MIN_RUN = (16, 3)

def split_mixed(segments, col, y_offset, protos, win=SPLIT_WINDOW, min_run=SPLIT_MIN_RUN):
    cols = trim_borders(col)
    rows = []
    for s in segments.itertuples():
        a = s.y_top - y_offset
        n = (s.y_bottom - s.y_top) // win
        if n < 2 * min_run:
            rows.append((s.y_top, s.y_bottom))
            continue
        windows = [describe(cols[a + i * win:a + (i + 1) * win]) for i in range(n)]
        lab = [int(np.argmin([descriptor_distance(w, p) for _, _, p in protos])) for w in windows]
        runs = []
        for i, l in enumerate(lab):
            if runs and runs[-1][0] == l:
                runs[-1][2] += 1
            else:
                runs.append([l, i, 1])
        kept = [r for r in runs if r[2] >= min_run] or [max(runs, key=lambda r: r[2])]
        starts = [r[1] for k, r in enumerate(kept) if k == 0 or r[0] != kept[k - 1][0]][1:]
        edges = [s.y_top] + [s.y_top + i * win for i in starts] + [s.y_bottom]
        rows += list(zip(edges[:-1], edges[1:]))
    return pd.DataFrame({'segment': range(len(rows)), 'y_top': [r[0] for r in rows], 'y_bottom': [r[1] for r in rows]})

def name_segments(segments, col, y_offset, protos, trim=2):
    cols = trim_borders(col)
    out = []
    for s in segments.itertuples():
        a, b = (s.y_top - y_offset, s.y_bottom - y_offset)
        if b - a > 4 * trim:
            a, b = (a + trim, b - trim)
        d = describe(cols[a:b])
        dist = np.array([descriptor_distance(d, p) for _, _, p in protos])
        order = np.argsort(dist)
        out.append({'legend_id': protos[order[0]][0], 'lithology': protos[order[0]][1], 'distance': dist[order[0]], 'margin': dist[order[1]] - dist[order[0]] if len(order) > 1 else 0.0})
    return pd.concat([segments[['y_top', 'y_bottom']].reset_index(drop=True), pd.DataFrame(out)], axis=1)

def merge_named(named):
    rows = []
    for r in named.itertuples():
        if rows and rows[-1]['legend_id'] == r.legend_id and (rows[-1]['y_bottom'] == r.y_top):
            rows[-1]['y_bottom'] = r.y_bottom
            rows[-1]['n_segments'] += 1
        else:
            rows.append({'y_top': r.y_top, 'y_bottom': r.y_bottom, 'legend_id': r.legend_id, 'lithology': r.lithology, 'n_segments': 1})
    return pd.DataFrame(rows)

def lithology_layers(segments, col, y_offset, legend, img, split=True):
    protos = prototypes(legend, img)
    if split:
        segments = split_mixed(segments, col, y_offset, protos)
    named = name_segments(segments, col, y_offset, protos)
    return (named, merge_named(named))
